import React from "react";
import { Link } from "gatsby";
import { postPath } from "../lib/content.cjs";
import { seriesPath } from "../lib/series.cjs";
export default function SeriesNavigation({ post, nodes, compact = false }) {
  if (!post.series) return null;
  const parts = nodes.filter(n => n.frontmatter.series === post.series)
    .sort((a, b) => a.frontmatter.seriesOrder - b.frontmatter.seriesOrder);
  const index = parts.findIndex(n => n.frontmatter.slug === post.slug);
  const previous = parts[index - 1]?.frontmatter;
  const next = parts[index + 1]?.frontmatter;
  return (
    <nav className="series-navigation" aria-label={compact ? "Previous and next parts" : "Tutorial series"}>
      {!compact && <>
        <Link className="series-label" to={seriesPath(post.series)}>{post.seriesTitle}</Link>
        <p>Part {post.seriesOrder} · {parts.length} {parts.length === 1 ? "part available" : "parts available"}</p>
        <details>
          <summary>In this series</summary>
          <ol>
            {parts.map(({ frontmatter: part }) => <li key={part.slug} value={part.seriesOrder}>
              <Link to={postPath(part.slug)} aria-current={part.slug === post.slug ? "page" : undefined}>
                {part.title}{part.draft ? " (Draft)" : ""}
              </Link>
            </li>)}
          </ol>
        </details>
      </>}
      <div className="series-pagination">
        {previous && <Link rel="prev" to={postPath(previous.slug)}>← Previous: {previous.title}</Link>}
        {next && <Link rel="next" to={postPath(next.slug)}>Next: {next.title} →</Link>}
      </div>
    </nav>
  );
}
