import React from "react";
import { Link } from "gatsby";
import { GatsbyImage, getImage } from "gatsby-plugin-image";
import { ArrowLeft, Clock3 } from "lucide-react";
import TitleTags from "./titleTags";
import { withSizes } from "../lib/images";
// The cover spans the reading column.
const coverSizes = "(min-width: 1109px) 760px, (min-width: 1001px) calc(100vw - 349px), (min-width: 761px) calc(100vw - 286px), (min-width: 481px) calc(100vw - 40px), calc(100vw - 32px)";
export default function PostTitle({ data, tags }) {
  const post = data.mdx.frontmatter;
  const image = withSizes(getImage(post.featuredImage), coverSizes);
  return (
    <header className="article-header enter">
      <Link className="back-link" to="/blog/">
        <ArrowLeft size={15} aria-hidden="true" /> Back to writing
      </Link>
      <TitleTags tags={tags} />
      {post.draft && <span className="draft-label">Draft</span>}
      <h1>{post.title}</h1>
      {post.description && <p className="article-deck">{post.description}</p>}
      <div className="article-byline">
        <Link to="/about/">Ahmad Roshanfar</Link>
        <span className="byline-meta">
          <time dateTime={post.rawDate}>{post.date}</time>
          <span aria-hidden="true">·</span>
          <span className="byline-reading">
            <Clock3 size={14} aria-hidden="true" /> {data.mdx.fields.readingMinutes} min read
          </span>
          {post.updated && (
            <>
              <span aria-hidden="true">·</span>
              <span>Updated {post.updated}</span>
            </>
          )}
        </span>
      </div>
      {image && (
        <div className="article-cover">
          <GatsbyImage
            image={image}
            alt={post.featuredImageAlt || post.title}
            loading="eager"
            imgStyle={{ objectFit: "cover" }}
          />
        </div>
      )}
    </header>
  );
}
