/* eslint-disable jsx-a11y/no-noninteractive-tabindex -- Scrollable regions need keyboard focus for horizontal scrolling. */
import React, { useEffect, useRef, useState } from "react";
import { PrismLight as SyntaxHighlighter } from "react-syntax-highlighter";
import bash from "react-syntax-highlighter/dist/esm/languages/prism/bash";
import javascript from "react-syntax-highlighter/dist/esm/languages/prism/javascript";
import json from "react-syntax-highlighter/dist/esm/languages/prism/json";
import css from "react-syntax-highlighter/dist/esm/languages/prism/css";
import python from "react-syntax-highlighter/dist/esm/languages/prism/python";
import c from "react-syntax-highlighter/dist/esm/languages/prism/c";
import cmake from "react-syntax-highlighter/dist/esm/languages/prism/cmake";
import qml from "react-syntax-highlighter/dist/esm/languages/prism/qml";
import cpp from "react-syntax-highlighter/dist/esm/languages/prism/cpp";
import dart from "react-syntax-highlighter/dist/esm/languages/prism/dart";
import { dracula } from "react-syntax-highlighter/dist/esm/styles/prism";
import { Check, Copy } from "lucide-react";
import { track } from "../../lib/analytics";
Object.entries({ bash, javascript, json, css, python, c, cpp, dart, cmake, qml }).forEach(
  ([name, syntax]) => SyntaxHighlighter.registerLanguage(name, syntax),
);
const SHELLS = new Set(["bash", "sh", "shell", "console", "zsh"]);
// Sized in em so code follows the article's text size setting.
const codeStyle = {
  margin: 0,
  background: "transparent",
  fontSize: ".84em",
  lineHeight: 1.7,
};
export default function CodeViewer({ code, language = "bash" }) {
  const [status, setStatus] = useState("");
  const source = code.replace(/\n$/, "");
  const timer = useRef(null);
  useEffect(() => () => clearTimeout(timer.current), []);
  async function copy() {
    try {
      await navigator.clipboard.writeText(code);
      setStatus("Copied!");
      track("copy_code", { language, page_path: window.location.pathname });
    } catch {
      setStatus("Select the code to copy it");
    }
    clearTimeout(timer.current);
    timer.current = setTimeout(() => setStatus(""), 2500);
  }
  // A one-line command reads as a single line, without a toolbar above it.
  if (SHELLS.has(language) && !source.includes("\n")) {
    return (
      <div className="code-block code-block-command">
        <div
          className="code-scroll"
          tabIndex={0}
          role="region"
          aria-label={`${language} command`}
        >
          <SyntaxHighlighter
            language={language}
            style={dracula}
            customStyle={{ ...codeStyle, padding: ".85rem 1.1rem" }}
          >
            {source}
          </SyntaxHighlighter>
        </div>
        <button className="code-copy" onClick={copy} aria-label="Copy code">
          {status === "Copied!" ? <Check size={15} aria-hidden="true" /> : <Copy size={15} aria-hidden="true" />}
          <span className="code-copy-status" aria-hidden="true">{status}</span>
        </button>
        <span className="sr-only" role="status">
          {status}
        </span>
      </div>
    );
  }
  return (
    <div className="code-block">
      <div className="code-toolbar">
        <span>{language}</span>
        <button onClick={copy} aria-label="Copy code">
          {status === "Copied!" ? <Check size={14} aria-hidden="true" /> : <Copy size={14} aria-hidden="true" />}
          <span aria-hidden="true">{status || "Copy"}</span>
        </button>
        <span className="sr-only" role="status">
          {status}
        </span>
      </div>
      <div
        className="code-scroll"
        tabIndex={0}
        role="region"
        aria-label={`${language} code`}
      >
        <SyntaxHighlighter
          language={language}
          style={dracula}
          customStyle={{ ...codeStyle, padding: "1.2rem 1.35rem" }}
        >
          {source}
        </SyntaxHighlighter>
      </div>
    </div>
  );
}
