/* eslint-disable jsx-a11y/no-noninteractive-tabindex -- Scrollable regions need keyboard focus for horizontal scrolling. */
import React from "react";
import CodeViewer from "./codeViewer";

export function MdxPre({ children, ...props }) {
  const child = React.Children.toArray(children)[0];
  if (!React.isValidElement(child) || typeof child.props.children !== "string") {
    return <pre {...props}>{children}</pre>;
  }
  const language = /\blanguage-(\S+)/.exec(child.props.className || "")?.[1] || "text";
  return <CodeViewer code={child.props.children} language={language} />;
}

const textOf = (node) => {
  if (typeof node === "string" || typeof node === "number") return String(node);
  if (Array.isArray(node)) return node.map(textOf).join("");
  return React.isValidElement(node) ? textOf(node.props.children) : "";
};
const childOfType = (node, type) =>
  React.Children.toArray(node).find((child) => React.isValidElement(child) && child.type === type);

// Name each scrollable table by its columns so the regions can be told apart.
function tableLabel(children) {
  const row = childOfType(childOfType(children, "thead")?.props.children, "tr");
  const columns = React.Children.toArray(row?.props.children)
    .map((cell) => textOf(cell).trim())
    .filter(Boolean);
  return columns.length ? `Table: ${columns.join(", ")}` : "Article table";
}

export function MdxTable(props) {
  return (
    <div className="table-scroll" role="region" aria-label={tableLabel(props.children)} tabIndex={0}>
      <table {...props} />
    </div>
  );
}
